package com.sakti.banking.controller; import com.sakti.banking.dto.*; import com.sakti.banking.entity.AccountStatus; import com.sakti.banking.service.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/admin") public class AdminController {private final UserService users;private final AccountService accounts;public AdminController(UserService u,AccountService a){users=u;accounts=a;} @GetMapping("/users") public List<UserResponse> users(){return users.allUsers();} @PatchMapping("/accounts/{n}/status") public AccountResponse status(@PathVariable String n,@RequestParam AccountStatus status){return accounts.setStatus(n,status);} }
